            SayLine(id: "s018-8", who: "Robotnik", de: "Und der letzte Punkt?", pl: "A ostatni punkt?"),
            SayLine(id: "s018-9", who: "Ty", de: "Die Baustelle selbst betrete ich nicht.", pl: "Na samą budowę nie wchodzę."),
            SayLine(id: "s018-10", who: "Robotnik", de: "Soll ich jemanden anrufen?", pl: "Mam do kogoś zadzwonić?"),
            SayLine(id: "s018-11", who: "Ty", de: "Noch nicht. Ich schreibe, wenn ich fertig bin.", pl: "Jeszcze nie. Napiszę, jak skończę."),
