            SayLine(id: "s019-2", who: "Szef", de: "Gut. Fang an der Rampe an.", pl: "Dobrze. Zacznij przy rampie."),
            SayLine(id: "s019-3", who: "Ty", de: "Mache ich. Ich schreibe, wenn ich da bin.", pl: "Tak zrobię. Napiszę, jak będę na miejscu."),

            SayLine(id: "s019-4", who: "Szef", de: "Ich fasse es nicht allein zusammen. Sag du.", pl: "Nie zbieram tego sam. Mów ty."),
            SayLine(id: "s019-5", who: "Ty", de: "Der Bus hat Verspätung, ich rufe den Chef an.", pl: "Autobus ma opóźnienie, dzwonię do szefa."),
