            SayLine(id: "s019-7", who: "Ty", de: "Ich sage die neue Zeit, nicht nur Entschuldigung.", pl: "Mówię nową godzinę, nie samo przepraszam."),
            SayLine(id: "s019-8", who: "Szef", de: "Gibt es noch einen Haken?", pl: "Jest jeszcze jakiś haczyk?"),
            SayLine(id: "s019-9", who: "Ty", de: "Ich schreibe auch die Haltestelle.", pl: "Dopisuję też przystanek."),
            SayLine(id: "s019-10", who: "Szef", de: "Wie lange brauchst du?", pl: "Ile czasu potrzebujesz?"),
            SayLine(id: "s019-11", who: "Ty", de: "Nicht lange. Danach bin ich weg.", pl: "Niedługo. Potem mnie nie ma."),
