            SayLine(id: "s117-6", who: "Ty", de: "Die Nachbarin klopft, weil ich am Sonntagmittag gebohrt habe.", pl: "Sąsiadka puka, bo w niedzielę w południe wierciłem."),
            SayLine(id: "s117-7", who: "Sąsiadka", de: "Passt das so?", pl: "Tak jest dobrze?"),
            SayLine(id: "s117-8", who: "Ty", de: "Ich höre auf.", pl: "Kończę."),
            SayLine(id: "s117-9", who: "Sąsiadka", de: "Was ist, wenn es nicht klappt?", pl: "Co, jak się nie uda?"),
            SayLine(id: "s117-10", who: "Ty", de: "Am Werktag nach achtzehn Uhr mache ich den Rest.", pl: "W dzień roboczy po osiemnastej robię resztę."),
            SayLine(id: "s117-11", who: "Sąsiadka", de: "Hast du alles dabei?", pl: "Masz wszystko przy sobie?"),
            SayLine(id: "s117-12", who: "Ty", de: "Ja. Ich prüfe es noch einmal und gehe.", pl: "Tak. Sprawdzam jeszcze raz i idę."),
